42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        HttpHeaders headers = new HttpHeaders();
107	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
108	        if (!normalizeNewOwner(owner)) {
109	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
110	        }
111	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.CONFLICT);
113	        }
114	        Optional<Owner> householdMember = findHouseholdMember(owner);
115	        if (householdMember.isPresent()) {
116	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
117	                return new ResponseEntity<>(HttpStatus.CONFLICT);
118	            }
119	            joinHousehold(owner, householdMember.get());
120	        }
121	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
122	        owner.setNamesakeCount(countNamesakes(owner));
123	        owner.setMembershipNumber(membershipNumber(owner));
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
132	    @Override
133	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
134	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
135	        if (currentOwner == null) {
136	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
137	        }
138	        currentOwner.setAddress(ownerFieldsDto.getAddress());
139	        currentOwner.setCity(ownerFieldsDto.getCity());
140	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
141	        currentOwner.setLastName(ownerFieldsDto.getLastName());
142	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
143	        String email = ownerFieldsDto.getEmail();
144	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
145	        this.clinicService.saveOwner(currentOwner);
146	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
147	    }
148	
149	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
150	    @Transactional
151	    @Override
152	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
153	        Owner owner = this.clinicService.findOwnerById(ownerId);
154	        if (owner == null) {
155	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
156	        }
157	        this.clinicService.deleteOwner(owner);
158	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        HttpHeaders headers = new HttpHeaders();
169	        Pet pet = petMapper.toPet(petFieldsDto);
170	        owner.setId(ownerId);
171	        pet.setOwner(owner);
172	        pet.getType().setName(null);
173	        this.clinicService.savePet(pet);
174	        PetDto petDto = petMapper.toPetDto(pet);
175	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
176	            .buildAndExpand(pet.getId()).toUri());
177	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
181	    @Override
182	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
183	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
184	        if (currentOwner != null) {
185	            Pet currentPet = this.clinicService.findPetById(petId);
186	            if (currentPet != null) {
187	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
188	                currentPet.setName(petFieldsDto.getName());
189	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
190	                this.clinicService.savePet(currentPet);
191	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
192	            }
193	        }
194	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
195	    }
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
200	        HttpHeaders headers = new HttpHeaders();
201	        Visit visit = visitMapper.toVisit(visitFieldsDto);
202	        Pet pet = new Pet();
203	        pet.setId(petId);
204	        visit.setPet(pet);
205	        this.clinicService.saveVisit(visit);
206	        VisitDto visitDto = visitMapper.toVisitDto(visit);
207	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
208	            .buildAndExpand(visit.getId()).toUri());
209	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
210	    }
211	
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
216	        Owner owner = this.clinicService.findOwnerById(ownerId);
217	        if (owner != null) {
218	            Pet pet = owner.getPet(petId);
219	            if (pet != null) {
220	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
221	            }
222	        }
223	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
224	    }
225	
226	    /**
227	     * Normalise the incoming fields of a freshly-mapped owner in place, applying
228	     * the canonical form each stored value must take: the address is trimmed,
229	     * whitespace-collapsed, upper-cased and its common abbreviations expanded, the
230	     * telephone is converted to E.164, any email is lower-cased and a missing
231	     * registration date defaults to today. Field-level rejections are reported here
232	     * rather than inline in {@link #addOwner}, and normalisation runs before any
233	     * household comparison so those comparisons see the canonical values.
234	     *
235	     * @param owner the freshly-mapped owner to normalise
236	     * @return {@code true} if the fields are valid, or {@code false} if the address
237	     *         is blank after normalisation or the telephone cannot form a valid
238	     *         E.164 number, in which case the request must be rejected with
239	     *         {@code 400 Bad Request}
240	     */
241	    private boolean normalizeNewOwner(Owner owner) {
242	        String address = Owner.normalizeAddress(owner.getAddress());
243	        if (address.isEmpty()) {
244	            return false;
245	        }
246	        owner.setAddress(address);
247	        String telephone = toE164(owner.getTelephone());
248	        if (telephone == null) {
249	            return false;
250	        }
251	        owner.setTelephone(telephone);
252	        if (owner.getEmail() != null) {
253	            owner.setEmail(owner.getEmail().toLowerCase());
254	        }
255	        if (owner.getRegistrationDate() == null) {
256	            owner.setRegistrationDate(LocalDate.now());
257	        }
258	        return true;
259	    }
260	
261	    /**
262	     * Find an existing owner that belongs to the same household as the given owner,
263	     * i.e. shares the same last name and address (compared case-insensitively with
264	     * runs of whitespace collapsed to a single space).
265	     *
266	     * @param owner the candidate owner being created
267	     * @return the matching existing owner, or empty if none exists
268	     */
269	    private Optional<Owner> findHouseholdMember(Owner owner) {
270	        return this.clinicService.findAllOwners().stream()
271	            .filter(existing -> existing.sameHouseholdAs(owner))
272	            .findFirst();
273	    }
274	
275	    /**
276	     * Assign the joining owner and an existing household member the same stable
277	     * household identifier. The identifier is derived deterministically from the
278	     * shared household key (last name + address, normalised), so every owner in a
279	     * household resolves to the same value; the existing member is updated when it
280	     * does not already carry it.
281	     *
282	     * @param owner    the owner being created
283	     * @param existing an existing owner in the same household
284	     */
285	    private void joinHousehold(Owner owner, Owner existing) {
286	        String householdId = UUID
287	            .nameUUIDFromBytes(owner.householdKey().getBytes(StandardCharsets.UTF_8)).toString();
288	        owner.setHouseholdId(householdId);
289	        if (!householdId.equals(existing.getHouseholdId())) {
290	            existing.setHouseholdId(householdId);
291	            this.clinicService.saveOwner(existing);
292	        }
293	    }
294	
295	    /**
296	     * Count the existing owners that share the given owner's first and last name,
297	     * compared case-insensitively (surrounding whitespace trimmed). Evaluated
298	     * before the new owner is saved, so the result reflects only owners that
299	     * already existed at creation time.
300	     *
301	     * @param owner the candidate owner being created
302	     * @return the number of existing namesakes
303	     */
304	    private int countNamesakes(Owner owner) {
305	        String firstName = normalizeName(owner.getFirstName());
306	        String lastName = normalizeName(owner.getLastName());
307	        return (int) this.clinicService.findAllOwners().stream()
308	            .filter(existing -> normalizeName(existing.getFirstName()).equals(firstName)
309	                && normalizeName(existing.getLastName()).equals(lastName))
310	            .count();
311	    }
312	
313	    private static String normalizeName(String value) {
314	        return value == null ? "" : value.trim().toLowerCase();
315	    }
316	
317	    /**
318	     * Build the next customer code, formatted {@code <CITY3>-<LAST3>-<NNNN>}: CITY3
319	     * is the upper-cased first three letters of the given city, LAST3 the upper-cased
320	     * first three letters of the given last name and NNNN a per-city 4-digit
321	     * zero-padded sequence equal to one more than the number of owners already in
322	     * that city (e.g. {@code SYD-SMI-0007}).
323	     *
324	     * @param city     the owner's city
325	     * @param lastName the owner's last name
326	     * @return the assigned customer code
327	     */
328	    private String nextCustomerCode(String city, String lastName) {
329	        String city3 = prefix3(city);
330	        String last3 = prefix3(lastName);
331	        long sequence = this.clinicService.findAllOwners().stream()
332	            .filter(existing -> normalizeName(existing.getCity()).equals(normalizeName(city)))
333	            .count() + 1L;
334	        return String.format("%s-%s-%04d", city3, last3, sequence);
335	    }
336	
337	    private static String prefix3(String value) {
338	        String v = value == null ? "" : value;
339	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
340	    }
341	
342	    /**
343	     * Build the owner's membership number, formatted {@code <customerCode>-M<YY>}
344	     * where {@code <customerCode>} is the owner's already-assigned customer code and
345	     * YY is the last two digits of the registration date's year (e.g.
346	     * {@code SMI-0007-M26}). Evaluated after the customer code and registration date
347	     * have been set.
348	     *
349	     * @param owner the owner being created, with customer code and registration date
350	     *              already assigned
351	     * @return the assigned membership number
352	     */
353	    private String membershipNumber(Owner owner) {
354	        int yy = owner.getRegistrationDate().getYear() % 100;
355	        return String.format("%s-M%02d", owner.getCustomerCode(), yy);
356	    }
357	
358	    /**
359	     * Normalise a telephone number to E.164 form: keep a leading '+' and country
360	     * code when present, otherwise assume country code '+61' and drop a single
361	     * leading '0' from the national digits. Spaces, dashes and brackets are
362	     * stripped. The result must contain 8 to 15 digits after the '+'.
363	     *
364	     * @return the E.164 string (e.g. "+61412345678"), or {@code null} if the
365	     *         input cannot form a valid E.164 number.
366	     */
367	    private static String toE164(String raw) {
368	        if (raw == null) {
369	            return null;
370	        }
371	        String cleaned = raw.replaceAll("[\\s()-]", "");
372	        String digits;
373	        if (cleaned.startsWith("+")) {
374	            digits = cleaned.substring(1);
375	        } else {
376	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
377	            digits = "61" + national;
378	        }
379	        if (!digits.matches("\\d{8,15}")) {
380	            return null;
381	        }
382	        return "+" + digits;
383	    }
384	}
